    'global.emails.user_data_collected_email_collector.body' => 'Përshëndetje, <strong>{{NAME}}</strong>,<br /><br />Sapo more të dhëna të reja nga një prej vizitorëve të tu përmes <strong>Email Collector</strong>.<br /><br /><strong>Email:</strong> {{DATA_EMAIL}}<br /><strong>Emri:</strong> {{DATA_NAME}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Shiko të gjitha të dhënat e mbledhura</a><br /><br />Përshëndetje,<br />Ekipi i {{WEBSITE_TITLE}}.',
    'global.emails.user_data_collected_contact_collector.body' => 'Përshëndetje, <strong>{{NAME}}</strong>,<br /><br />Sapo more një dërgim të ri të të dhënave nga <strong>formulari i kontaktit</strong> i një prej vizitorëve të tu.<br /><br /><strong>Email:</strong> {{DATA_EMAIL}}<br /><strong>Telefoni:</strong> {{DATA_PHONE}}<br /><strong>Emri:</strong> {{DATA_NAME}}<br /><strong>Mesazhi:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Shiko të gjitha të dhënat e mbledhura</a><br /><br />Përshëndetje,<br />Ekipi i {{WEBSITE_TITLE}}.',
    'global.emails.user_data_collected_appointment_calendar.body' => 'Përshëndetje, <strong>{{NAME}}</strong>,<br /><br />Sapo more një rezervim të ri në <strong>Appointment Calendar</strong> nga një prej vizitorëve të tu.<br /><br /><strong>Data:</strong> {{DATA_DATE}}<br /><strong>Ora:</strong> {{DATA_TIME}}<br /><strong>Kohëzgjatja:</strong> {{DATA_DURATION}}<br /><strong>Email:</strong> {{DATA_EMAIL}}<br /><strong>Telefoni:</strong> {{DATA_PHONE}}<br /><strong>Emri:</strong> {{DATA_NAME}}<br /><strong>Mesazhi:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Shiko të gjitha të dhënat e mbledhura</a><br /><br />Të fala,<br />Ekipi i {{WEBSITE_TITLE}}.',
