    'global.emails.user_plan_expired.subject' => 'Plani yt ka skaduar: {{WEBSITE_TITLE}}',
    'global.emails.user_plan_expired.body' => 'Përshëndetje, <strong>{{NAME}}</strong>,<br /><br />Plani yt <strong>{{PLAN_NAME}}</strong> ka skaduar, pasi nuk e ke rinovuar anëtarësimin.<br /><br />Nëse dëshiron të vazhdosh ta përdorësh faqen tonë me të gjitha veçoritë që kishe, duhet ta rinovosh anëtarësimin.<br /><br /><a href="{{USER_PLAN_RENEW_LINK}}" class="cta">Rinovo planin</a><br /><br />Përshëndetje,<br />Ekipi i {{WEBSITE_TITLE}}.',
