    'global.emails.auto_delete_inactive_users.subject' => 'Llogaria jote është fshirë: {{WEBSITE_TITLE}}',
    'global.emails.auto_delete_inactive_users.body' => 'Përshëndetje, <strong>{{NAME}}</strong>,<br /><br />Ky është një email i thjeshtë për të të njoftuar se llogaria jote është fshirë për shkak të pasivitetit për më shumë se {{INACTIVITY_DAYS}} ditë.<br /><br />Nëse dëshiron të rifitosh qasjen, duhet të regjistrosh një llogari tjetër tek ne.<br /><br /><a href="{{REGISTER_LINK}}" class="cta">Regjistrohu përsëri</a><br /><br />Përshëndetje,<br />Ekipi i {{WEBSITE_TITLE}}.',
