    'dashboard.onboarding_intro.text' => 'FCC të ofron një aplikacion personal, përmbajtje blogu, mjete për funnel, mbështetje dhe rekomandime nga AI, që të krijosh më shumë interes për produktet Forever, regjistrimet dhe kontaktet.',
    'dashboard.onboarding_intro.item_1_title' => 'Aplikacionet FCC dhe lidhjet për ndarje',
