    'dashboard.onboarding_modal.step_1_title' => '1. Paneli si pikënisja jote',
    'dashboard.onboarding_modal.step_1_text' => 'Paneli është vendi yt kryesor për të kuptuar sistemin FCC: këtu shikon treguesin e aktivitetit, udhëzuesit edukativë, veprimet e radhës dhe përmbledhjen e asaj që tashmë po sjell rezultate.',
    'dashboard.onboarding_modal.step_2_title' => '2. Menutë kryesore dhe përmbajtja',
    'dashboard.onboarding_modal.step_2_text' => 'Përmes menysë kryesore hap përmbajtjen Forever Card Club, Forever Products, blogun, kontaktet dhe panelin. Kjo është rruga që përdor për të mësuar, për të ndarë përmbajtje dhe për të zhvilluar biznesin tënd Forever.',
    'dashboard.onboarding_modal.step_3_title' => '3. Aplikacionet dhe lidhjet FCC',
    'dashboard.onboarding_modal.step_3_text' => 'Aplikacionet e tua FCC shërbejnë si baza jote personale digjitale, nga e cila i drejton vizitorët te produktet, regjistrimet, kontaktet dhe veprime të tjera të rëndësishme.',
    'dashboard.onboarding_modal.step_4_title' => '4. Blogu dhe rekomandimet',
    'dashboard.onboarding_modal.step_4_text' => 'Blogu dhe seksioni Forever Products përdoren për të ndarë përmbajtje edukative dhe përmbajtje për produktet, bashkë me rekomandimin tënd, në mënyrë që interesi për produktet dhe dyqanin online të mbetet i lidhur me ty.',
    'dashboard.onboarding_modal.step_5_title' => '5. Sinjali, AI dhe plani yt i rritjes',
    'dashboard.onboarding_modal.step_5_text' => 'FCC ndjek cilat veprime të çojnë vërtet te dyqani online i Forever dhe AI e përdor këtë sinjal për të sugjeruar hapat e ardhshëm më të qartë dhe një plan më të mirë rritjeje.',
    'dashboard.onboarding_modal.step_6_title' => '6. Mbështetja, edukimi dhe temat e webinarëve',
    'dashboard.onboarding_modal.step_6_text' => 'Kur ngec ose dëshiron një drejtim të ri, mbështetja dhe temat e webinareve të japin shpjegime shtesë, ndihmë dhe mundësinë të sugjerosh çfarë ka më shumë rëndësi për fazën tënde të ardhshme të zhvillimit.',
    'dashboard.onboarding_modal.primary' => 'Nis udhëzuesin',
    'dashboard.onboarding_modal.secondary' => 'Thjesht më trego si funksionon',
    'dashboard.tutorials.eyebrow' => 'Udhëzues të shpejtë',
    'dashboard.tutorials.title' => 'Udhëzime për rekomandimet e tua të para',
    'dashboard.tutorials.text' => 'Hap udhëzues të shkurtër për veprime të caktuara që të ndihmojnë të shtosh interesin, klikimet dhe rekomandimet përmes sistemit FCC.',
    'dashboard.tutorials.blog_referral.badge' => 'Blogu i FCC + rekomandim',
    'dashboard.tutorials.blog_referral.title' => 'Ndaj një artikull me lidhjen tënde të rekomandimit',
    'dashboard.tutorials.blog_referral.text' => 'Ky udhëzues të çon nga seksioni Forever Products te një lidhje e gatshme që lidh automatikisht përmbajtjen, rekomandimin dhe vizitën në dyqanin online.',
    'dashboard.tutorials.blog_referral.button' => 'Udhëzuesi i fillimit',
    'dashboard.tutorials.blog_referral.modal_title' => 'Si të ndash një artikull me lidhjen tënde të rekomandimit',
    'dashboard.tutorials.blog_referral.modal_subtitle' => 'Nga hapja e seksionit Forever Products deri te kopjimi i një lidhjeje të gatshme që përmban tashmë rekomandimin tënd.',
    'dashboard.tutorials.blog_referral.modal_callout' => 'Kur ndan një artikull në këtë mënyrë, FCC e shton automatikisht rekomandimin tënd te lidhja që dërgon. Kjo është mënyra më e thjeshtë që përmbajtja për produktin të funksionojë menjëherë për sinjalin dhe rekomandimin tënd.',
    'dashboard.tutorials.blog_referral.modal_primary' => 'Nis udhëzuesin hap pas hapi',
    'dashboard.tutorials.blog_referral.next_open_article' => 'Hap artikullin',
    'dashboard.tutorials.blog_referral.step_1_title' => '1. Kliko Forever Products',
    'dashboard.tutorials.blog_referral.step_1_text' => 'Hap seksionin Forever Products në menynë majtas. Kjo të çon te blogu me përmbajtje për produktet, gati për t\'u shpërndarë.',
    'dashboard.tutorials.blog_referral.step_2_title' => '2. Zgjidh një produkt ose gjeje përmes kërkimit',
    'dashboard.tutorials.blog_referral.step_2_text' => 'Brenda blogut, zgjidh produktin që dëshiron të rekomandosh. Nëse dëshiron të gjesh më shpejt artikullin e duhur, përdor kërkimin dhe hap produktin që përputhet me interesin e personit.',
    'dashboard.tutorials.blog_referral.step_3_title' => '3. Përdor hapësirën e ndarjes me rekomandimin',
    'dashboard.tutorials.blog_referral.step_3_text' => 'Në krye të artikullit do të shohësh seksionin Ndaje këtë faqe me rekomandimin tënd. Aty mund ta kopjosh lidhjen ose ta ndash menjëherë me butonat e disponueshëm.',
    'dashboard.tutorials.blog_referral.step_4_title' => '4. Lidhja tashmë përfshin rekomandimin tënd',
    'dashboard.tutorials.blog_referral.step_4_text' => 'Lidhja që kopjon ose ndan përmban tashmë lidhjen tënde unike të rekomandimit. Nëse një vizitor hap dyqanin online të Forever përmes saj, ajo vizitë dhe rekomandimi lidhen me llogarinë tënde.',
    'dashboard.tutorials.blog_referral.step_5_title' => 'Pse ka rëndësi',
    'dashboard.tutorials.blog_referral.step_5_text' => 'Këto klikime forcojnë sinjalin e shitjeve, ndihmojnë në pozicionimin e aplikacionit tënd Forever Card dhe krijojnë një gjurmë të qartë interesi drejt Forever Living Products.',
    'dashboard.tutorials.blog_referral.category_step_1_title' => 'Tani je te produktet Forever',
    'dashboard.tutorials.blog_referral.category_step_1_text' => 'Kjo është pjesa e blogut të produkteve me përmbajtje që mund ta ndash përmes rekomandimit tënd. Udhëzuesi tani të çon te artikulli i duhur dhe te lidhja e rekomandimit që mund të ndash.',
    'dashboard.tutorials.blog_referral.category_step_2_title' => 'Gjej produktin që dëshiron të rekomandosh',
    'dashboard.tutorials.blog_referral.category_step_2_text' => 'Nëse e di tashmë cilin produkt dëshiron të dërgosh, shkruaje në kërkim. Kjo është mënyra më e shpejtë për të gjetur artikullin që përputhet me interesin e personit.',
    'dashboard.tutorials.blog_referral.category_step_3_title' => 'Hap artikullin për produktin',
    'dashboard.tutorials.blog_referral.category_step_3_text' => 'Për këtë udhëzues do të hapim artikullin e parë të dukshëm. Brenda artikullit, udhëzuesi do të vazhdojë dhe do të të tregojë ku ta kopjosh ose ndash lidhjen e rekomandimit.',
    'dashboard.tutorials.blog_referral.article_step_1_title' => 'Këtu krijohet lidhja e rekomandimit',
    'dashboard.tutorials.blog_referral.article_step_1_text' => 'Në krye të artikullit mund të shohësh rreshtin e ndarjes me rekomandimin tënd. Kur ndan nga kjo pjesë, FCC shton rekomandimin tënd personal te lidhja.',
    'dashboard.tutorials.blog_referral.article_step_2_title' => 'Shiko si funksionon sistemi',
    'dashboard.tutorials.blog_referral.article_step_2_text' => 'Klikimi te Si funksionon kjo hap një shpjegim të shkurtër se rekomandimi yt shtohet automatikisht dhe se vizita mbetet e lidhur me llogarinë tënde.',
    'dashboard.tutorials.blog_referral.article_step_3_title' => 'Ndaje artikullin duke përdorur butonat e gatshëm',
    'dashboard.tutorials.blog_referral.article_step_3_text' => 'Këtu mund ta ndash menjëherë artikullin në rrjetet sociale ose ta dërgosh me mesazh. Të gjitha opsionet përdorin të njëjtën lidhje me rekomandimin tënd.',
    'dashboard.tutorials.blog_referral.article_step_4_title' => 'Kopjo lidhjen tënde të përfunduar',
    'dashboard.tutorials.blog_referral.article_step_4_text' => 'Nëse dëshiron ta vendosësh vetë lidhjen në një mesazh, histori ose postim, kopjoje këtu. Një vizitor që hyn në dyqanin online të Forever përmes kësaj lidhjeje mbetet i lidhur me rekomandimin tënd.',
    'dashboard.tour.launch' => 'Nis udhëzuesin',
    'dashboard.tour.replay' => 'Riluaj udhëzuesin',
    'dashboard.tour.next' => 'Tjetër',
    'dashboard.tour.prev' => 'Prapa',
    'dashboard.tour.skip' => 'Kaloje',
    'dashboard.tour.finish' => 'Përfundo',
    'dashboard.tour.step_guide_title' => 'Udhëzuesi për këtë faqe',
    'dashboard.tour.step_guide_text' => 'Në çdo faqe të rëndësishme të FCC, udhëzuesin e gjen në këndin e sipërm djathtas. Kliko atë buton sa herë të duhen udhëzime të shkurtra, hap pas hapi, për faqen që po shikon.',
    'dashboard.tour.step_sidebar_title' => 'Menuja dhe fushat e punës së FCC',
    'dashboard.tour.step_sidebar_text' => 'Kjo është menyja kryesore FCC brenda sistemit tënd të përdoruesit. Nga këtu hap panelin kryesor, aplikacionet, planin tënd të rritjes, rezultatet, edukimin dhe përmbajtjen e produkteve që të ndihmojnë në aktivitetin e përditshëm të biznesit Forever.',
    'dashboard.tour.step_menu_apps_title' => 'Aplikacionet FCC',
    'dashboard.tour.step_menu_apps_text' => 'Këtu hap aplikacionet e Forever Card. Ato janë baza jote dixhitale personale për t’i orientuar vizitorët drejt produkteve, regjistrimeve, kontakteve dhe veprimeve të tjera kryesore.',
    'dashboard.tour.step_menu_ai_plan_title' => 'Plani i rritjes me AI',
    'dashboard.tour.step_menu_ai_plan_text' => 'Këtu hap dhe ndjek planin tënd të rritjes. AI përdor sinjalet nga aplikacionet e tua, përmbajtja e blogut dhe klikimet në dyqanin online për të sugjeruar hapat më të mirë të radhës për ditët në vijim.',
    'dashboard.tour.step_menu_results_title' => 'Rezultatet e FCC',
    'dashboard.tour.step_menu_results_text' => 'Këtu mund të shohësh nëse sistemi yt po sjell vërtet rezultate. Kjo hapësirë të ndihmon të ndjekësh klikimet, përparimin dhe treguesit që tregojnë se çfarë ia vlen të forcosh.',
    'dashboard.tour.step_menu_education_title' => 'Edukimi Forever',
    'dashboard.tour.step_menu_education_text' => 'Kjo hapësirë përmban materiale edukative me video dhe shpjegime që të ndihmojnë ta kuptosh sistemin, të ndjekësh hapat dhe ta zbatosh atë që mëson në punën e përditshme.',
    'dashboard.tour.step_menu_products_title' => 'Produktet Forever',
    'dashboard.tour.step_menu_products_text' => 'Këtu hapen artikujt e produkteve dhe përmbajtjet me rekomandime. Është një nga vendet kryesore nga ku ndan përmbajtje me personin të cilit i bën rekomandime dhe e orienton interesin e klientëve potencialë drejt dyqanit online Forever.',
    'dashboard.tour.step_navbar_title' => 'Menyja kryesore e FCC',
    'dashboard.tour.step_navbar_text' => 'Menyja e sipërme është navigimi yt kryesor përmes materialeve edukative, produkteve, përmbajtjes së blogut, kontaktit dhe kthimit te paneli. Këtu nis të kuptuarit e gjithë sistemit FCC.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Kjo hap informacionin kryesor të FCC, shpjegimet e sistemit dhe përmbajtjen që të ndihmon të kuptosh si bashkëveprojnë aplikacionet, rekomandimet dhe mjetet për të ndërtuar një biznes Forever.',
    'dashboard.tour.step_menu_forever_products_title' => 'Produktet Forever',
    'dashboard.tour.step_menu_forever_products_text' => 'Këtu hapen përmbajtje për produktet dhe artikuj që mund t’i ndash bashkë me rekomandimin tënd. Kjo është pjesë e rëndësishme e ngjalljes së interesit dhe e orientimit të vizitorëve drejt dyqanit online Forever.',
    'dashboard.tour.step_menu_blog_title' => 'Blogu',
    'dashboard.tour.step_menu_blog_text' => 'Blogu të ofron përmbajtje më të gjerë edukative dhe biznesi, të cilën mund ta përdorësh në postime e mesazhe dhe për të ndërtuar besim përmes përmbajtjes së dobishme, jo vetëm përmes shitjes së drejtpërdrejtë.',
    'dashboard.tour.step_menu_contact_title' => 'Kontakt',
    'dashboard.tour.step_menu_contact_text' => 'Këtu mund të kontaktosh dhe të marrësh mbështetje për pyetje të tjera. Kur diçka nuk është e qartë ose të duhet orientim, kjo është një nga vendet ku mund të kërkosh ndihmë.',
    'dashboard.tour.step_menu_dashboard_title' => 'Shko te paneli',
    'dashboard.tour.step_menu_dashboard_text' => 'Paneli yt është qendra jote e komandimit. Këtu ndjek sinjalet e tua, mëson përmes udhëzuesve, sheh çfarë funksionon dhe vendos cili duhet të jetë hapi yt i radhës.',
    'dashboard.tour.step_hero_title' => 'Faqja kryesore e punës sate në FCC',
    'dashboard.tour.step_hero_text' => 'Kjo pjesë e sipërme përmbledh se ku ndodhesh tani, cili është fokusi yt dhe cilat janë pikat më të shpejta të hyrjes te aplikacionet, mbështetja dhe udhëzuesit edukativë.',
    'dashboard.tour.step_growth_title' => 'Sinjalet dhe zhbllokimet',
    'dashboard.tour.step_growth_text' => 'Këtu mund të shohësh sa aktivitet real drejtohet drejt dyqanit online Forever Living përmes aplikacionit tënd FCC, blogut dhe mjeteve të tjera. Ky sinjal përcakton ritmin e ndihmës me AI dhe hapat e ardhshëm që zhbllokohen në planin tënd të zhvillimit.',
    'dashboard.tour.step_tutorials_title' => 'Mini udhëzime dhe edukim',
    'dashboard.tour.step_tutorials_text' => 'Këtu hap udhëzues të shkurtër dhe praktikë për veprime të caktuara. Kështu funksionon edukimi i FCC në praktikë, jo vetëm përmes teorisë, por edhe përmes hapave të vegjël që mund t\'i zbatosh menjëherë.',
    'dashboard.tour.step_workbench_title' => 'Tavolina e punës',
    'dashboard.tour.step_workbench_text' => 'Këtu sheh menjëherë çfarë funksionon, ku humbet rezultati dhe cilat pjesë të sistemit tashmë po tërheqin interes. Kjo të ndihmon të marrësh vendime bazuar në sinjale reale, jo në hamendësime.',
    'dashboard.tour.step_chart_title' => 'Klikime që sjellin rezultate',
    'dashboard.tour.step_chart_text' => 'Grafiku i ndan burimet aplikacioni → Forever, blogu → Forever, regjistrimet dhe kontaktet nga funnel-i dhe biseda me AI, që të shohësh qartë se cila pjesë e sistemit krijon sinjalin e vërtetë të biznesit.',
    'dashboard.tour.step_next_action_title' => 'Hapi yt i radhës',
    'dashboard.tour.step_next_action_text' => 'Ky bllok të jep një rekomandim të qartë për atë që duhet të bësh tani. Qëllimi i FCC nuk është të të mbingarkojë me të dhëna, por të të ndihmojë të zgjedhësh hapin vijues më të dobishëm.',
    'dashboard.tour.step_support_title' => 'Temat e mbështetjes dhe webinareve',
    'dashboard.tour.step_support_text' => 'Këtu mund të kontaktosh mbështetjen, të lexosh përgjigjet e administratorëve dhe të sugjerosh tema për webinarët që dëshiron të trajtojmë. Është pjesë e edukimit të FCC dhe të ndihmon kur ngec ose dëshiron të kuptosh më shumë.',
