    'fcc_results.proof_note' => 'FCC Results tregojnë treguesit e aktivitetit. Featured Apps janë shembujt publikë me 15+ / 30d, ndërsa 50+ / 30d e forcon më tej rrugën drejt sponsorëve të rekomanduar në faqen kryesore.',
    'fcc_results.metrics_note' => 'Pragjet dhe renditjet numërojnë vizitat e kualifikuara te Forever përmes butonave dhe blogjeve të zakonshëm e të posaçëm, me mbrojtje kundër përsëritjeve. Vetëm një etiketë UTM nuk jep pikë. Kontributi i kualifikimit për VIP funnel shfaqet veçmas; kontaktet e tjera nga funnel dhe bisedat me AI tregojnë interes.',
