    'fcc_results.tips.item_6' => 'Ndaj një produkt nga blogu yt përmes lidhjes së shpërndarjes në një story ose dërgoja drejtpërdrejt kontakteve të interesuara me mesazh, për të shtuar vizitat në Forever Shop me rekomandimin tënd.',
