    'ai_plan.signal_summary.signal_label' => 'Sinjali aktual',
    'ai_plan.signal_summary.signal_text_default' => 'Ka disa sinjale, por ato ende nuk janë mjaftueshëm të forta për t\'u shndërruar në një rezultat të qëndrueshëm pa një fokus më të qartë.',
    'ai_plan.signal_summary.signal_text_zero' => 'Ende nuk ka sinjal real nga Forever Webshop. Qëllimi i parë nuk është të shtohet kompleksiteti, por të sigurohen klikimet e para cilësore që kanë kuptim.',
    'ai_plan.signal_summary.signal_text_building' => 'Për momentin ke %s klikime në Forever Webshop gjatë 30 ditëve të fundit. Të duhen të paktën %s që plani javor të bazohet te sinjale reale dhe jo te supozimet.',
    'ai_plan.signal_summary.signal_text_ready' => 'Ke %s klikime në Forever Webshop gjatë 30 ditëve të fundit, që do të thotë se sistemi tani mund ta krijojë planin javor bazuar në sjelljen reale të vizitorëve.',
    'ai_plan.signal_summary.action_label' => 'Veprimi më i dobishëm për momentin',
    'ai_plan.signal_summary.action_text_default' => 'Mbaje fokusin të ngushtë: një mesazh i qartë, një drejtim kryesor dhe një aplikacion që do ta përdorësh vërtet këtë javë.',
    'ai_plan.signal_summary.action_text_direct' => 'Burimi i vizitës shpesh nuk është i qartë. Këtë javë, mos i shpërndaj përpjekjet. Përdor një format të përsëritshëm dhe një rrugë të qartë drejt Forever Shop.',
    'ai_plan.signal_summary.action_text_recruitment' => 'Nëse fokusi yt është biznesi, përdor një histori të qartë dhe një ftesë për të biseduar këtë javë, në vend që të dërgosh shumë mesazhe dhe oferta njëherësh.',
    'ai_plan.signal_summary.action_text_building' => 'Përparësi ka tërheqja e klikimeve të para cilësore drejt Forever Webshop përmes një veprimtarie të përsëritshme, jo nisja e disa ideve njëherësh.',
    'ai_plan.signal_summary.action_text_funnel_live' => 'Tani %s nga %s hapat e shitjes janë aktivë. Këtë javë fokusi duhet të jetë te mbajtja e rrugës së qartë, që vizitori të mos ketë nevojë të zgjedhë shumë gjëra njëherësh.',
    'ai_plan.signal_summary.action_text_sales_ready' => 'Sinjali është mjaftueshëm i fortë që këtë javë të përqendrohesh te kthimi i interesit në veprime në dyqanin online, jo thjesht te rritja e vizitave.',
    'ai_plan.signal_summary.action_text_weekly_ready' => 'Sinjali është gati. Tani kontrolli javor ka rëndësi, sepse plani nuk nis më nga hamendësimet, por nga sjellja reale e vizitorëve.',
    'ai_plan.signal_summary.watch_label' => 'Çfarë duhet ndjekur nga afër',
    'ai_plan.signal_summary.watch_text_default' => 'Mos e bëj aplikacionin ose aktivitetet e tua javore më të ndërlikuara nga sa mund të përballojë sinjali aktual. Qartësia ka më shumë rëndësi se gjerësia.',
    'ai_plan.signal_summary.watch_text_mobile' => 'Shumica e njerëzve e shohin faqen tënde në telefon. Ekrani i parë, mesazhi i parë dhe klikimi i parë duhet të jenë të qarta menjëherë, pa shumë lëvizje poshtë ose zgjedhje.',
    'ai_plan.signal_summary.watch_text_funnel_early' => 'Hapat e shitjes ekzistojnë tashmë, por sinjali mbetet i dobët. Mos e bëj rrugëtimin tepër të ndërlikuar shumë herët nëse ende nuk ka klikime cilësore në fillim.',
    'ai_plan.signal_summary.watch_text_country' => 'Pjesa më e madhe e interesit vjen aktualisht nga ky treg: %s. Sigurohu që mesazhi, shembulli dhe oferta të jenë të qarta për këtë audiencë.',
    'ai_plan.status_card_title' => 'Statusi yt tani',
