    'ai_plan.status_card_text_signal' => 'Profili ekziston, por sinjali është ende duke u ndërtuar. Fokusi është të arrihen edhe %s klikime cilësore në Forever Webshop, që plani javor të ketë një bazë të qëndrueshme.',
    'ai_plan.status_card_text_weekly' => 'Sinjali është gati. Hapi tjetër më i vlefshëm është të plotësosh regjistrimin javor, që sistemi të përgatisë një plan javor konkret, jo një sugjerim të përgjithshëm.',
    'ai_plan.status_card_text_plan_pending' => 'Ekziston një kontroll javor, por plani ende nuk është ruajtur. Hapi i radhës është të hapësh planin aktual ose të presësh një paraqitje të re javore për një plan të ri.',
    'ai_plan.status_card_text_execute' => 'Plani është gati. Tani përqendrohu te zbatimi i tij pa u shpërndarë mes shumë ideve të reja, pastaj shëno rezultatin real.',
    'ai_plan.status_card_text_complete' => 'Cikli më i fundit ka përfunduar. Tani mund ta përdorësh rezultatin për të hyrë në kontrollin e ardhshëm javor me një drejtim shumë më të qartë.',
