    'featured_apps.header' => 'Aplikacionet e veçuara Forever Card',
    'featured_apps.subheader' => 'Kjo faqe shfaq aplikacionet kryesore publike të FCC nga bashkëpunëtorët që kanë arritur sinjalin 15+ gjatë 30 ditëve të fundit. Ata që arrijnë edhe 50+ brenda 30 ditëve e forcojnë statusin e tyre për t\'u rekomanduar si sponsorë në faqen kryesore, ndërsa 15+ brenda 7 ditëve shërben vetëm si kontroll i ritmit.',
