    'index.presentation5.header' => 'Ktheje interesin në biznes të vërtetë',
    'index.presentation5.subheader' => 'Me FCC Funnel mbledh kontakte më lehtë, bën ndjekje më shpejt dhe e sheh qartë se çfarë të sjell më shumë kërkesa, kontakte të interesuara dhe anëtarë të rinj të ekipit.',
