    'index.projects.header' => 'Projektet',
    'index.projects.subheader' => 'Mënyra më e lehtë për të kategorizuar burimet që menaxhon.',
    'index.file_links.header' => 'Lidhjet e skedarëve',
    'index.file_links.subheader' => 'Krijo lidhje dinamike dhe të avancuara për skedarët, të cilat mund të shkarkohen.',
    'index.vcard_links.header' => 'Kartëvizitë dixhitale',
    'index.vcard_links.subheader' => 'Krijo karta kontakti digjitale dinamike, të gjurmueshme dhe të shkarkueshme.',
    'index.splash_pages.header' => 'Faqet e uljes',
    'index.splash_pages.subheader' => 'Përdor faqe ndërmjetëse të personalizuara me numërim mbrapsht për lidhjet e tua.',
    'index.pixels.header' => 'Analitikë e avancuar dhe ndjekje e performancës',
    'index.pixels.subheader' => 'Të gjitha lidhjet inteligjente dhe aplikacioni Forever Card integrohen me platformat kryesore të analitikës dhe reklamimit.',
    'index.pixels.note' => 'Të dhënat e gjurmimit u lejojnë partnerëve të kuptojnë çfarë funksionon: cili përmbajtje nxit interesin, nga vijnë vizitorët dhe cilat fushata sjellin rezultate. Sistemi mbështet integrimin me ofruesit kryesorë të pikselëve dhe gjurmimit.',
    'index.pricing.header' => 'Çmime të thjeshta dhe transparente.',
    'index.testimonials.one.text' => 'Kjo platformë e ka transformuar plotësisht mënyrën se si i menaxhojmë rrjedhat tona të punës. Është intuitive dhe e shpejtë, dhe i ka kursyer ekipit tonë orë të panumërta çdo javë.',
    'index.testimonials.one.attribute' => 'Redaktor, Writer\'s Weekly',
    'index.testimonials.two.text' => 'Në fillim isha skeptik, por brenda pak ditësh pashë sa më produktiv u bë ekipi ynë. Ekipi i mbështetjes është gjithashtu jashtëzakonisht i përgjegjshëm.',
    'index.partners.header' => 'Pse partnerët përdorin Forever Card Club',
    'index.partners.subheader' => 'Një sistem dixhital i strukturuar për ndërtimin profesional dhe global të biznesit Forever.',
    'index.partners.card1.title' => 'Një sistem: gjithçka në një vend',
    'index.partners.card1.text' => 'Aplikacion personal, lidhje inteligjente, edukim, mbështetje me AI dhe analitika, të bashkuara në një ekosistem të vetëm digjital.',
    'index.partners.card2.title' => 'Ridrejtim global pa ndërlikime',
    'index.partners.card2.text' => 'Lidhjet inteligjente zbulojnë automatikisht shtetin e vizitorit dhe e lidhin me dyqanin zyrtar të Forever në rajonin e tij.',
    'index.partners.card3.title' => 'Prani profesionale në internet dhe jashtë tij',
    'index.partners.card3.text' => 'Aplikacioni personal dhe karta NFC mundësojnë ndarje të lehtë pa njohuri teknike.',
    'index.partners.card4.title' => 'Strukturë e qartë për rritje',
    'index.partners.card4.text' => 'Programi Udhëtimi im me 90 hapa praktikë dhe edukimi hap pas hapi i ndihmojnë partnerët të ndërtojnë një sistem të qëndrueshëm dhe afatgjatë.',
    'index.faq.header' => 'Përgjigje për pyetjet e zakonshme',
    'index.faq.one.question' => 'Si mund ta marr aplikacionin Forever Card?',
    'index.faq.one.answer' => 'Forever Card App të jepet kur bëhesh partner biznesi Forever i regjistruar dhe sponsori yt është në ekipin tonë. Pasi të të jepet qasja, ndjek një proces të thjeshtë orientimi që të tregon si ta aktivizosh dhe konfigurosh aplikacionin tënd personal. Aplikacioni yt është baza jote dixhitale: ti zgjedh cilat blloqe të shfaqësh, për shembull video, produkte, këshilltar AI, kontakte, edukim, dhe mund ta konfigurosh gjithçka pa aftësi teknike. Nëse punon edhe jashtë internetit, merr falas një kartë NFC që dërgohet në adresën tënde dhe që hap aplikacionin me një prekje ose skanim të shpejtë.',
    'index.faq.two.question' => 'Si funksionojnë porositja pa regjistrim dhe referimi?',
    'index.faq.two.answer' => 'Forever Card Club përdor lidhje inteligjente referimi të krijuara për t’u shpërndarë në mbarë botën. Kur një vizitor klikon lidhjen tënde ose zgjedh një produkt brenda aplikacionit tënd dhe zgjedh "porosit", sistemi mund ta zbulojë automatikisht shtetin e vizitorit dhe ta lidhë me dyqanin zyrtar online të Forever në shtetin e tij. Referimi yt është përfshirë në lidhje, në mënyrë që blerja të mund të lidhet me ty si partneri që e rekomandoi, në përputhje me rregullat zyrtare të sistemit. E rëndësishme: Forever Card Club nuk shet produkte. Të gjitha blerjet kryhen përmes dyqanit zyrtar online në shtetin e klientit.',
    'index.faq.three.question' => 'Çfarë marr si anëtar i ekipit?',
    'index.faq.three.answer' => 'Si anëtar i ekipit, merr një sistem të plotë për të ndërtuar një biznes Forever në internet, që përfshin: një aplikacion personal Forever Card (mjetet dhe përmbajtjet e tua në një vend), lidhje inteligjente referimi për drejtimin global te dyqani zyrtar në internet, një këshilltar me IA për udhëzime dhe informacion rreth produkteve brenda aplikacionit, udhëzime hap pas hapi (si ta përdorësh sistemin dhe të ndërtosh biznesin në internet), programin Udhëtimi im me 90 hapa praktikë dhe mbështetjen e sponsorit tënd, analitika (çfarë klikojnë njerëzit, nga vijnë dhe çfarë funksionon më mirë), si dhe një kartë NFC falas që dorëzohet në adresën tënde për kontaktet jashtë internetit. Gjithashtu, merr mbështetje nga komuniteti (për shembull, grupe WhatsApp dhe udhëzime të qarta) që të të ndihmojë të jesh i/e qëndrueshëm/e dhe të arrish rezultate afatgjata.',
    'index.faq.four.question' => 'Si funksionon programi Udhëtimi im?',
    'index.faq.four.answer' => 'Udhëtimi im është një program me 90 hapa praktikë për 90 ditë. Të udhëheq nga përgatitja e kartës dhe e mjeteve, përmes bisedave të para me klientët dhe një ritmi të rregullt postimesh, deri te ndihma për të tjerët dhe nisja e ekipit tënd. Çdo ditë merr një hap të qartë prej rreth 20 minutash, me një mesazh shembull dhe një pyetje për sponsorin tënd. 7 hapat e parë hapen menjëherë pas regjistrimit në FCC. Përparimi yt varet nga aktiviteti yt, ndërsa sponsori dhe Coach të ndihmojnë të ruash ritmin.',
    'index.faq.five.question' => 'Çfarë bën këshilluesi i IA-së brenda aplikacionit?',
    'index.faq.five.answer' => 'Këshilluesi me AI i ndihmon vizitorët ta gjejnë më lehtë informacionin. Bazuar në pyetjet e tyre, ai mund të sugjerojë informacione dhe produkte përkatëse, pastaj t\'i udhëzojë drejt hapit të radhës, të mësojnë më shumë, të kontaktojnë ose të bëjnë porosi. Nëse vizitori zgjedh të bëjë porosi, këshilluesi me AI mund ta drejtojë te dyqani zyrtar online përmes lidhjeve inteligjente, të cilat ruajnë lidhjen e referimit të partnerit. Për partnerët, kjo zvogëlon nevojën për të përsëritur informacionin bazë dhe ndihmon që komunikimi të jetë i qartë dhe i njëtrajtshëm.',
    'index.faq.contact_note' => 'Nëse dëshiron qasje ose ke ndonjë pyetje, na kontakto përmes %s.',
    'index.faq.contact_link' => 'Faqja e kontaktit',
