    'links.header' => 'Lidhjet',
    'links.subheader' => 'Krijo dhe menaxho të gjitha lidhjet e tua të personalizuara.',
    'links.short_links.guide_title' => 'Lidhjet e shkurtra, të shpjeguara aty ku njerëzit kanë nevojë',
    'links.short_links.guide_text' => 'Krijo një lidhje të shkurtër brenda pak sekondash, pastaj përdor Redakto për të përcaktuar se si funksionon. Kjo pamje tani i udhëzon njerëzit në krijim, menaxhim të listës, analiza dhe cilësime të avancuara të ridrejtimit, në mënyrë që të përdorin çdo mundësi me siguri.',
    'links.short_links.total_label' => 'Lidhje të shkurtra aktive',
    'links.short_links.guide_card_1_title' => 'Krijo shpejt',
    'links.short_links.guide_card_1_text' => 'Fillo me një URL destinacioni dhe, nëse dëshiron, cakto një alias të personalizuar. Nëse e lë bosh, sistemi krijon një për ty.',
    'links.short_links.guide_card_2_title' => 'Ndryshoje me një qëllim',
    'links.short_links.guide_card_2_text' => 'Hap Edit për të kontrolluar gjurmimin, rregullat e përkohshme, lidhjen me aplikacionin, mbrojtjen me fjalëkalim, fshehjen, shënjestrimin dhe sjellje të tjera të ridrejtimit.',
    'links.short_links.guide_card_3_title' => 'Menaxho në shkallë të gjerë',
    'links.short_links.guide_card_3_text' => 'Përdor importimin në masë, filtrat, kopjimin, QR, dublikimin, rivendosjen dhe ndryshimin e statusit për ta mbajtur të organizuar një bibliotekë më të madhe lidhjesh.',
    'links.short_links.guide_card_4_title' => 'Mat atë që funksionon',
    'links.short_links.guide_card_4_text' => 'Kontrollo statistikat për të parë cilat lidhje të shkurtra japin rezultatet më të mira, pastaj përmirëso konfigurimin tënd drejtpërdrejt nga ekrani i redaktimit.',
