    'qr_codes.title' => 'Kodet QR',
    'qr_codes.menu' => 'Kodet QR',
    'qr_codes.breadcrumb' => 'Kodet QR',
    'qr_codes.header' => 'Kodet QR',
    'qr_codes.subheader' => 'Krijo lehtësisht kode QR të personalizueshme dhe ruaji për t\'i përdorur më vonë.',
    'qr_codes.page_intro' => 'Krijo kode QR të pavarura për shtyp, ndarje jashtë linje, evente, produkte, WiFi, ndarje të kontakteve dhe shumë raste të tjera. Çdo Forever Card App mund të krijojë edhe QR-në e vet të drejtpërdrejtë, ndërsa kjo pjesë të ofron një hapësirë të veçantë për krijimin dhe redaktimin e kodeve QR, të gjitha në një vend.',
    'qr_codes.guide_title' => 'Një hapësirë e veçantë QR për printim, ndarje jashtë linje dhe përdorime të kontrolluara',
    'qr_codes.guide_text' => 'Ky seksion QR shërben për kodet QR të pavarura që dëshiron t’i menaxhosh jashtë një ekrani të caktuar të aplikacionit. Përdore kur të duhen kode QR për printim, kode fushatash të ripërdorshme, pika hyrëse për evente ose produkte, ose një kod QR që meriton stil dhe proces të vetin eksportimi.',
    'qr_codes.guide_card_1_title' => 'I ndarë nga QR-ja e aplikacionit',
    'qr_codes.guide_card_1_text' => 'Çdo aplikacion Forever Card mund të krijojë kodin e vet të drejtpërdrejtë QR, por këtu mund të krijosh kode QR krejtësisht të veçanta për faqe të tjera uljeje, lidhje, materiale dhe fushata.',
    'qr_codes.guide_card_2_title' => 'Krijuar për printim dhe përdorim jashtë internetit',
    'qr_codes.guide_card_2_text' => 'Këto kode QR janë ideale për fletushka, karta biznesi, postera, fletë produktesh, tavolina eventesh, ambalazhe dhe ndarje ballë për ballë, ku njerëzit skanojnë në vend që të shkruajnë.',
    'qr_codes.guide_card_3_title' => 'Përshtate dhe eksporto siç duhet',
    'qr_codes.guide_card_3_text' => 'Kontrollo llojin e kodit QR, stilin, ngjyrat, kornizat, logon, identitetin vizual dhe formatin e skedarit, që kodi përfundimtar t’i përshtatet kontekstit ku do të përdoret.',
    'qr_codes.guide_card_4_title' => 'Modifikoje dhe ripërdore më vonë',
    'qr_codes.guide_card_4_text' => 'Pasi krijohet, çdo kod QR mbetet i disponueshëm për shkarkim, printim, kopjim dhe përmirësime të mëvonshme, pa pasur nevojë ta krijosh përsëri nga e para.',
    'qr_codes.empty_title' => 'Krijo kodin tënd të parë QR',
    'qr_codes.empty_text' => 'Fillo me një kod QR të pavarur për një lidhje, aplikacion, kontakt, aktivitet ose material të shtypur. Pas krijimit, mund të kthehesh për të ndryshuar stilin, kornizën, markën dhe formatin e eksportit.',
    'qr_codes.tour.create_title' => 'Krijo një kod QR të pavarur',
    'qr_codes.tour.create_text' => 'Përdore këtë buton kur dëshiron një QR që përdoret jashtë një faqeje të vetme të Forever Card App. Është ideal për fushata, materiale të shtypura, evente dhe shpërndarje të përsëritshme jashtë internetit.',
    'qr_codes.tour.guide_title' => 'Kupto kur kjo pjesë është vendi i duhur',
    'qr_codes.tour.guide_text' => 'Ky udhëzues shpjegon ndryshimin midis kodeve QR specifike për aplikacionin dhe elementeve QR më vete. Qëllimi është t’i ndihmojë përdoruesit të zgjedhin rrjedhën e duhur përpara se të krijojnë ose të modifikojnë.',
    'qr_codes.tour.list_title' => 'Biblioteka jote e kodeve QR qëndron e organizuar këtu',
    'qr_codes.tour.list_text' => 'Kjo listë bëhet qendra e kontrollit për çdo kod QR të pavarur: parapamja, emri, lloji, lidhja me projektin, veprimet e eksportimit dhe qasja për modifikim janë të gjitha bashkë.',
    'qr_codes.tour.row_title' => 'Çdo rresht është një material QR i ripërdorshëm',
    'qr_codes.tour.row_text' => 'Një kod QR këtu mund të përmbajë një URL, lidhje aplikacioni, ngjarje, lidhje për WiFi, vCard, kërkesë pagese ose shumë përvoja të tjera që hapen me skanim. Mund të vazhdosh ta përmirësosh të njëjtin element me kalimin e kohës.',
    'qr_codes.tour.actions_title' => 'Shkarko, printo, modifiko, kopjo',
    'qr_codes.tour.actions_text' => 'Përdor veprimet në anën e djathtë për të eksportuar në formate të ndryshme, për të hapur Edit, për të kopjuar një kod QR funksional për një fushatë të re ose për të hequr materialet e vjetra që nuk të duhen më.',
    'qr_codes.create' => 'Krijo QR',
