    'qr_codes.empty_error_message' => 'Sigurohu që të plotësosh fushat e përmbajtjes së kodit QR.',
    'qr_code_create.breadcrumb' => 'Krijo kod QR',
    'qr_code_create.title' => 'Krijo kod QR',
    'qr_code_create.header' => 'Krijo kod QR',
    'qr_code_update.breadcrumb' => 'Ndrysho kodin QR',
    'qr_code_update.title' => 'Ndrysho kodin QR',
    'qr_code_update.header' => 'Ndrysho kodin QR',
    'qr_codes.editor.hero_title' => 'Ktheje një QR të thjeshtë në një pikë hyrjeje të ripërdorshme nga offline në dixhital',
    'qr_codes.editor.hero_text' => 'Ky redaktues e kthen kodin QR në diçka praktike, me identitetin tënd të markës dhe gati për përdorim real. Çdo Forever Card App mund të gjenerojë kodin e vet QR, por këtu mund të krijosh dhe përpunosh veçmas kode QR për materiale të shtypura, fushata, evente, udhëtime rreth produkteve, ndarjen e kontakteve dhe shumë raste të tjera skanimi.',
    'qr_codes.editor.hero_card_1_title' => 'Zgjidh rezultatin e skanimit',
    'qr_codes.editor.hero_card_1_text' => 'Vendos nëse kodi QR duhet të hapë një URL, kartë kontakti, proces pagese, lidhje WiFi, draft mesazhi, event, vendndodhje apo një veprim tjetër të mbështetur.',
    'qr_codes.editor.hero_card_2_title' => 'Përshtate me kontekstin',
    'qr_codes.editor.hero_card_2_text' => 'Rregullo stilin, ngjyrat, kornizën, markën dhe logon opsionale, në mënyrë që kodi QR të përshtatet me një fletushkë, kartëvizitë, fletë produkti, prezantim ose material për event.',
    'qr_codes.editor.hero_card_3_title' => 'Shiko paraprakisht para printimit',
    'qr_codes.editor.hero_card_3_text' => 'Përdor pamjen paraprake drejtpërdrejt, kontrollin e lexueshmërisë dhe opsionet e shkarkimit për ta testuar përpara se kodi QR të printohet ose të shpërndahet publikisht.',
    'qr_codes.editor.hero_card_4_title' => 'Ripërdor në vend që ta rindërtosh',
    'qr_codes.editor.hero_card_4_text' => 'Pasi një kod QR të funksionojë mirë, vazhdo ta redaktosh, ta kopjosh ose ta eksportosh për fushata të reja, në vend që të fillosh nga e para çdo herë.',
    'qr_codes.editor.tour.intro_title' => 'Përmbledhje e redaktuesit të QR',
    'qr_codes.editor.tour.intro_text' => 'Kjo faqe të ndihmon të krijosh ose përpunosh një kod QR të pavarur që mund të printohet, shpërndahet, eksportohet dhe ripërdoret në shumë kontekste.',
    'qr_codes.editor.tour.type_title' => 'Zgjidh se çfarë duhet të bëjë skanimi',
    'qr_codes.editor.tour.type_text' => 'Lloji i kodit QR përcakton veprimin që kryen personi që e skanon: hap një lidhje, ruan të dhënat e kontaktit, nis një mesazh, lidhet me WiFi, shfaq një kërkesë pagese e të tjera.',
    'qr_codes.editor.tour.basics_title' => 'Fillo me emrin dhe të dhënat kryesore',
    'qr_codes.editor.tour.basics_text' => 'Jepi kodit QR një emër të qartë të brendshëm dhe plotëso fushat kryesore të përmbajtjes. Kjo është përmbajtja bazë që do të përfshihet në kod.',
    'qr_codes.editor.tour.style_title' => 'Formëso vetë modelin QR',
    'qr_codes.editor.tour.style_text' => 'Stili përcakton formën e moduleve dhe të syve të kodit QR. Kjo është e dobishme kur kodi QR duhet të përputhet vizualisht me një markë, fushatë ose material të shtypur.',
    'qr_codes.editor.tour.colors_title' => 'Kontrollo kontrastin dhe qartësinë e skanimit',
    'qr_codes.editor.tour.colors_text' => 'Ngjyrat nuk janë vetëm çështje estetike. Kontrasti i mirë është thelbësor për skanimin e besueshëm, veçanërisht kur kodi QR printohet ose shihet në kushte ndriçimi jo të përsosura.',
    'qr_codes.editor.tour.frame_title' => 'Shto kontekst rreth kodit QR',
    'qr_codes.editor.tour.frame_text' => 'Kornizat e bëjnë kodin QR të duket më i qëllimshëm dhe mund të përfshijnë një thirrje për veprim ose një etiketë, në mënyrë që njerëzit ta kuptojnë menjëherë pse duhet ta skanojnë.',
    'qr_codes.editor.tour.branding_title' => 'Shto me kujdes logon dhe elementet e markës',
    'qr_codes.editor.tour.branding_text' => 'Mundësitë e markës të lejojnë të vendosësh logo dhe imazhe në përbërjen e kodit QR, por ato duhet të testohen me kujdes që lexueshmëria të mbetet e mirë.',
    'qr_codes.editor.tour.options_title' => 'Përfundo cilësimet teknike',
    'qr_codes.editor.tour.options_text' => 'Madhësia, margjina, kodimi, korrigjimi i gabimeve dhe organizimi i projektit ndihmojnë që kodi QR të funksionojë siç duhet gjatë eksportimit dhe përdorimit në prodhim.',
    'qr_codes.editor.tour.preview_title' => 'Shiko drejtpërdrejt kodin QR përfundimtar',
    'qr_codes.editor.tour.preview_text' => 'Parapamja të lejon të konfirmosh që kodi QR duket i qartë dhe mund të skanohet para se ta shkarkosh, printosh ose ndash.',
    'qr_codes.editor.tour.download_title' => 'Përgatit daljen për printim ose dorëzim',
    'qr_codes.editor.tour.download_text' => 'Eksporto në SVG, PNG, JPG ose WEBP, në varësi të faktit nëse të duhet cilësi për printim, transparencë, përdorim në prezantime apo shpërndarje e shpejtë.',
    'qr_codes.editor.tour.save_title' => 'Ruaje, testo, pastaj publikoje',
    'qr_codes.editor.tour.save_text' => 'Pas ruajtjes, skano kodin QR në të paktën një telefon para se ta përdorësh publikisht. Kjo është veçanërisht e rëndësishme kur përdoren korniza, gradientë, logo ose materiale të printuara.',
    'biolink_block_delete.header' => 'Fshi bllokun',
    'biolink_block_delete.subheader' => 'Të gjitha të dhënat që lidhen me bllokun FCC do të fshihen plotësisht. Ky veprim nuk mund të zhbëhet.',
    'biolink_block_delete.success_message' => 'Fshirja e bllokut FCC u krye me sukses.',
    'biolink_block.title' => 'Blloku FCC',
    'links_statistics.title' => 'Statistikat e lidhjeve',
    'links_statistics.menu' => 'Statistikat e lidhjeve',
    'links_statistics.breadcrumb' => 'Statistikat e lidhjeve',
    'links_statistics.header' => 'Statistikat e lidhjeve',
    'link.header.subheader' => 'Aplikacioni Forever Card: %s',
    'link.header.short_link_subheader' => 'Cilësimet e lidhjes së shkurtër: %s',
    'link.short_editor.hero_title' => 'Ktheje një URL të shkurtër të thjeshtë në një rrjedhë ridrejtimi të kontrolluar',
    'link.short_editor.hero_text' => 'Ky redaktues është vendi ku një lidhje e shkurtër bëhet strategjike. Përveç pseudonimit dhe destinacionit, mund të shtosh planifikimin, gjurmimin UTM, mbrojtjen me fjalëkalim, lidhjen me aplikacionin, fshehjen e lidhjes, synimin sipas pajisjes ose vendndodhjes, sjelljen HTTP dhe kontrolle të tjera të avancuara.',
    'link.short_editor.hero_card_1_title' => 'Fillo me bazat',
    'link.short_editor.hero_card_1_text' => 'Përcakto URL-në e destinacionit, zgjidh një alias të shkurtër dhe vendos se cilin domen duhet të përdorë lidhja e shkurtër.',
    'link.short_editor.hero_card_2_title' => 'Vendos si funksionon',
    'link.short_editor.hero_card_2_text' => 'Kontrollo kur funksionon lidhja, ku ridrejton, çfarë ndodh pas skadimit dhe nëse duhet të përcjellë parametrat e kërkimit.',
    'link.short_editor.hero_card_3_title' => 'Ndiq dhe personalizo',
    'link.short_editor.hero_card_3_text' => 'Shto etiketa UTM, pikselë, meta të dhëna maskimi dhe lidhje me aplikacionin, që çdo klikim të përmbajë kontekstin që të nevojitet.',
    'link.short_editor.hero_card_4_title' => 'Mbro dhe optimizo',
    'link.short_editor.hero_card_4_text' => 'Përdor fjalëkalime, paralajmërime për përmbajtje delikate, synim të audiencës dhe kode ridrejtimi për t\'iu përshtatur çdo fushate dhe audience.',
    'link.short_editor.form_title' => 'Çfarë mund të konfigurosh në një lidhje të shkurtër',
    'link.short_editor.form_text' => 'Hap vetëm seksionet që të duhen ose ndiq udhëzuesin hap pas hapi. Secili grup më poshtë kontrollon një shtresë të përvojës së lidhjeve të shkurtra, nga ridrejtimet e thjeshta deri te logjika e avancuar e fushatave.',
    'link.short_editor.card_1_title' => 'Për lançime pa pengesa',
    'link.short_editor.card_1_text' => 'Cakto destinacionin, pseudonimin, domenin dhe kodin e ridrejtimit, që lidhja të funksionojë pikërisht siç dëshiron që nga shpërndarja e parë.',
    'link.short_editor.card_2_title' => 'Për fushata dhe raportim',
    'link.short_editor.card_2_text' => 'Shto vlera UTM, pikselë, raporte dhe projekte që trafiku të mund të matet dhe të grupohet siç duhet.',
    'link.short_editor.card_3_title' => 'Për sjellje të avancuar',
    'link.short_editor.card_3_text' => 'Cakto kur është i disponueshëm orari, rregullat e skadimit, mbrojtjen e qasjes dhe audiencat e synuara, ose fshih faqen e destinacionit kur nevojitet.',
    'link.short_editor.tour.intro_title' => 'Përmbledhje e redaktuesit të lidhjeve të shkurtra',
    'link.short_editor.tour.intro_text' => 'Kjo faqe përmbledh të gjitha opsionet e avancuara për një lidhje të shkurtër. Qëllimi është i thjeshtë: t\'i ndihmojë njerëzit të kuptojnë se çfarë ndryshon çdo cilësim përpara se ta ruajnë.',
    'link.short_editor.tour.basics_title' => 'Së pari, gjërat bazë',
    'link.short_editor.tour.basics_text' => 'Këtu përcakton se ku të çon lidhja e shkurtër, çfarë aliasi përdor dhe në cilin domen duhet të jetë. Këto janë cilësimet bazë të ridrejtimit.',
    'link.short_editor.tour.app_linking_title' => 'Hap drejtpërdrejt aplikacionet celulare',
    'link.short_editor.tour.app_linking_text' => 'Lidhja e aplikacionit ndihmon që destinacionet e mbështetura në celular të hapen brenda aplikacionit vendas dhe jo vetëm në shfletues, gjë që mund të përmirësojë përvojën e përdoruesit në telefona.',
    'link.short_editor.tour.temporary_title' => 'Vendos rregullat e kohëzgjatjes dhe skadimit',
    'link.short_editor.tour.temporary_text' => 'Përdore këtë seksion për të caktuar disponueshmërinë, për të kufizuar klikimet ose për të përcaktuar se ku shkojnë njerëzit pasi skadon lidhja. Është ideale për promovime, lançime dhe fushata me kohë të kufizuar.',
    'link.short_editor.tour.utm_title' => 'Shto kontekstin e analitikës',
    'link.short_editor.tour.utm_text' => 'Parametrat UTM i ndihmojnë mjetet analitike të kuptojnë burimin, mediumin dhe fushatën e trafikut. Ky është një nga vendet më të dobishme për të standardizuar emërtimin e fushatave të tua.',
    'link.short_editor.tour.protection_title' => 'Mbroje qasjen kur nevojitet',
    'link.short_editor.tour.protection_text' => 'Fjalëkalimet dhe paralajmërimet për përmbajtje të ndjeshme janë të dobishme kur një lidhje nuk duhet të jetë plotësisht e hapur ose kur vizitorët kanë nevojë për kontekst para se të vazhdojnë.',
    'link.short_editor.tour.targeting_title' => 'Dërgo audienca të ndryshme në destinacione të ndryshme',
    'link.short_editor.tour.targeting_text' => 'Përcaktimi i audiencës bën që një lidhje e shkurtër të reagojë sipas vendit, qytetit, pajisjes, sistemit operativ, gjuhës së shfletuesit ose rregullave të rotacionit. Kjo është e dobishme për fushatat e segmentuara.',
    'link.short_editor.tour.cloaking_title' => 'Kontrollo pamjen paraprake që shohin njerëzit',
    'link.short_editor.tour.cloaking_text' => 'Cloaking ndryshon titullin, përshkrimin, imazhin dhe të dhëna të tjera meta që shfaqen para ridrejtimit. Është i dobishëm kur pamja paraprake e shpërndarë duhet të përputhet me mesazhin e fushatës.',
    'link.short_editor.tour.http_title' => 'Zgjidh llojin e ridrejtimit',
    'link.short_editor.tour.http_text' => '301, 302, 307 dhe 308 nuk janë identike. Ky seksion përcakton nëse ridrejtimi konsiderohet i përhershëm apo i përkohshëm dhe si duhet ta trajtojnë shfletuesit.',
    'link.short_editor.tour.advanced_title' => 'Përfundo me kontrollet e avancuara',
    'link.short_editor.tour.advanced_text' => 'Projektet, faqet hyrëse, njoftimet, përcjellja e kërkesave dhe opsionet përkatëse gjenden këtu, që lidhja e shkurtër të përshtatet në një proces më të gjerë pune.',
    'link.short_editor.tour.save_title' => 'Ruaj dhe testo',
    'link.short_editor.tour.save_text' => 'Pas ruajtjes, provo lidhjen e shkurtër në kompjuter dhe në celular, dhe kontrollo statistikat për t\'u siguruar që ridrejtimet, atribuimi dhe shënjestrimi funksionojnë siç pret.',
