    'create_link_modal.header' => 'URL e shkurtër',
    'create_link_modal.subheader' => 'Krijo lidhjen e shkurtër tani, pastaj hap Edit për të zhbllokuar cilësimet e avancuara të ridrejtimit, analitikën, shënjestrimin, maskimin e lidhjes dhe kontrollet e fushatës.',
    'create_link_modal.guide_title' => 'Nisje e shpejtë',
    'create_link_modal.guide_text' => 'Ngjit URL-në e gjatë të destinacionit, shto sipas dëshirës pseudonimin tënd dhe krijo lidhjen e shkurtër. Nëse pseudonimin e lë bosh, sistemi do të krijojë një automatikisht.',
    'create_link_modal.after_create_title' => 'Çfarë ndodh pas krijimit?',
    'create_link_modal.after_create_text' => 'Pasi të krijohet lidhja e shkurtër, zgjidh Edit nga menyja e veprimeve për të konfiguruar etiketat UTM, lidhjen me aplikacionin, disponueshmërinë e përkohshme, rregullat e skadimit, mbrojtjen me fjalëkalim, shënjestrimin, fshehjen dhe mënyrën e ridrejtimit.',
