    'create_link_modal.input.submit' => 'Shkurto URL-në',
    'create_link_modal.error_message.main_domain_is_disabled' => 'Nuk të lejohet të përdorësh domenin kryesor për të krijuar lidhje.',
    'biolink_modal.header' => 'Krijo aplikacionin Forever Card',
    'biolink_modal.subheader' => 'Hap një aplikacion të ri FCC për ofertën, tregun ose një fushatë të caktuar. Vendos bazën tani dhe rregulloje gjithçka më hollësisht menjëherë pas krijimit.',
    'biolink_modal.guide_title' => 'Nisje e shpejtë',
    'biolink_modal.guide_text' => 'Zgjidh një emërtim të shkurtër për lidhjen nëse dëshiron një version të personalizuar. Nëse e lë bosh, sistemi do të krijojë një të tillë automatikisht dhe aplikacioni do të jetë menjëherë gati për redaktim.',
