    'fcc.page.semantics_heading' => 'Çfarë është Forever Card Club (FCC)?',
    'fcc.page.semantics_summary' => 'Forever Card Club (FCC) është një sistem dixhital biznesi gjithëpërfshirës për partnerët e Forever Living Products. FCC ndërthur një aplikacion personal, lidhje inteligjente referimi, asistentë produktesh me AI, logjikën e funnel-it të kontakteve potenciale, edukimin, analizat dhe një kartë fizike NFC në një rrjedhë të vetme pune biznesi.',
    'fcc.page.semantics_fact_1' => 'Forever Card Club nuk është faqe interneti apo dyqan zyrtar i Forever Living Products, por një sistem i pavarur për partnerët.',
    'fcc.page.semantics_fact_2' => 'Aplikacioni Forever Card është aplikacioni personal që merr çdo anëtar, ndërsa FCC i referohet sistemit më të gjerë.',
