    'fcc.page.semantics_fact_4' => 'Sistemi është krijuar për shpërndarje online, drejtimin e referimeve, mbledhjen e kontakteve potenciale, udhëzime me AI dhe rritjen e biznesit Forever.',
    'fcc.page.semantics_solves_heading' => 'Çfarë zgjidh FCC?',
    'fcc.page.semantics_solve_1' => 'Një vend qendror për aplikacionin e partnerit, përmbajtjen, produktet dhe mënyrat e kontaktit.',
    'fcc.page.semantics_solve_2' => 'Drejtim më i zgjuar te dyqani zyrtar Forever në vendin e vizitorit.',
    'fcc.page.semantics_solve_3' => 'Mbledhja e të dhënave të personave të interesuar dhe ndjekja më e shpejtë pas interesimit ose rekomandimit.',
    'fcc.page.semantics_solve_4' => 'Zbulim produktesh dhe udhëzime për hapat e ardhshëm me ndihmën e AI brenda sistemit.',
    'fcc.page.semantics_solve_5' => 'Një lidhje e qartë nga kontakti jashtë internetit, përmes NFC/QR, te rrjedha e punës në internet.',
    'fcc.page.term_description' => 'Forever Card Club (FCC) është një sistem dixhital biznesi gjithëpërfshirës për partnerët e Forever Living Products, që përfshin një aplikacion personal, lidhje inteligjente referimi, asistentë AI për produktet, logjikë për rrjedhën e kontakteve të mundshme, edukim, analitikë dhe një kartë fizike NFC të lidhur me përmbajtjen dhe rekomandimet e partnerit.',
    'fcc.page.workflow_heading' => 'Si funksionon FCC në praktikë?',
    'fcc.page.workflow_intro' => 'Nga tërheqja e parë e vëmendjes deri te kontakti ose blerja, FCC i lidh hapat kryesorë në një rrjedhë të vetme biznesi.',
    'fcc.page.workflow_step_1_title' => 'Hyrja',
    'fcc.page.workflow_step_1_text' => 'Një postim, mesazh, kod QR ose kartë NFC e sjell vizitorin në sistem.',
    'fcc.page.workflow_step_2_title' => 'Aplikacioni',
    'fcc.page.workflow_step_2_text' => 'Aplikacioni Forever Card hap përmbajtje, produkte, veprime kontakti dhe rekomandime.',
    'fcc.page.workflow_step_3_title' => 'Udhëzim',
    'fcc.page.workflow_step_3_text' => 'AI-ja, lidhjet dhe blloqet e drejtojnë vizitorin drejt hapit të duhur të radhës.',
    'fcc.page.workflow_step_4_title' => 'Veprim',
    'fcc.page.workflow_step_4_text' => 'Vizitori lë të dhënat e kontaktit ose kalon drejt dyqanit zyrtar Forever.',
    'fcc.page.workflow_step_5_title' => 'Ndjekja e mëtejshme',
    'fcc.page.workflow_step_5_text' => 'Partneri ndjek interesimin dhe e vazhdon më lehtë bisedën.',
    'fcc.page.use_cases_heading' => 'Çfarë zgjidh FCC?',
    'fcc.page.use_cases_intro' => 'I njëjti sistem mbështet disa mënyra të ndryshme për të ndërtuar një biznes Forever.',
    'fcc.page.use_case_1_title' => 'Partner i ri',
    'fcc.page.use_case_1_text' => 'Të jep një fillim më të qartë në internet dhe një përshtypje të parë më profesionale.',
    'fcc.page.use_case_2_title' => 'Partner aktiv',
    'fcc.page.use_case_2_text' => 'Mund të lidhë rekomandimet, klientët e mundshëm dhe produktet në një rrjedhë të vetme pune.',
    'fcc.page.use_case_3_title' => 'Drejtues ekipi',
    'fcc.page.use_case_3_text' => 'Mund ta regjistrosh ekipin në të njëjtin sistem dhe ta kopjosh modelin më lehtë.',
    'fcc.page.use_case_4_title' => 'Ndarje online',
    'fcc.page.use_case_4_text' => 'Aplikacioni dhe lidhjet inteligjente e bëjnë shumë më të lehtë publikimin dhe ndarjen e drejtpërdrejtë.',
    'fcc.page.use_case_5_title' => 'Kontakt jashtë internetit',
    'fcc.page.use_case_5_text' => 'Karta NFC dhe rrjedha me QR u japin takimeve ballë për ballë një vazhdimësi dixhitale.',
    'fcc.page.use_case_6_title' => 'Rekomandime nga AI',
    'fcc.page.use_case_6_text' => 'Asistentët me inteligjencë artificiale i ndihmojnë vizitorët të gjejnë më shpejt një produkt të përshtatshëm dhe hapin e duhur të radhës.',
    'fcc.page.howto.forever_card_app.name' => 'Si të konfigurosh aplikacionin Forever Card',
    'fcc.page.howto.forever_card_app.description' => 'Hapat për konfigurimin e aplikacionit personal Forever Card brenda sistemit FCC.',
    'fcc.page.howto.forever_card_app.step_1' => 'Aktivizo aplikacionin Forever Card dhe konfirmo gjërat bazë për partnerin.',
    'fcc.page.howto.forever_card_app.step_2' => 'Shto përmbajtjen që dëshiron të shfaqësh: produkte, mënyra kontakti, rekomandime dhe informacione të dobishme.',
    'fcc.page.howto.forever_card_app.step_3' => 'Lidh lidhjet inteligjente të referimit dhe konfirmo që aplikacioni të çon te dyqani zyrtar online i Forever përkatës.',
