    'fcc.page.howto.smart_referral_links.description' => 'Hapat që shpjegojnë se si lidhjet inteligjente FCC i drejtojnë vizitorët te dyqani zyrtar Forever në internet.',
    'fcc.page.howto.smart_referral_links.step_1' => 'Partneri shpërndan një lidhje referimi përmes aplikacionit, një mesazhi ose një postimi.',
    'fcc.page.howto.smart_referral_links.step_2' => 'FCC zbulon nga vjen vizitori dhe zgjedh rrugën e duhur për tregun.',
    'fcc.page.howto.smart_referral_links.step_3' => 'Vizitori drejtohet te dyqani zyrtar online i Forever-it në vendin e tij.',
    'fcc.page.howto.smart_referral_links.step_4' => 'Referimi i partnerit mbetet i lidhur me rrugën drejt blerjes ose interesimit të mëtejshëm.',
    'fcc.page.howto.nfc_card_offline.name' => 'Si i kalon karta NFC vizitorët nga një takim ballë për ballë te aplikacioni FCC',
    'fcc.page.howto.nfc_card_offline.description' => 'Hapat që tregojnë se si karta NFC dhe kodi QR hapin udhëtimin digjital të FCC-së pas një takimi ballë për ballë.',
    'fcc.page.howto.nfc_card_offline.step_1' => 'Gjatë një takimi ballë për ballë, partneri paraqet kartën NFC ose kodin QR.',
    'fcc.page.howto.nfc_card_offline.step_2' => 'Vizitori hap aplikacionin Forever Card me një prekje ose skanim.',
    'fcc.page.howto.nfc_card_offline.step_3' => 'Brenda aplikacionit, ata shohin menjëherë produktet, mënyrat e kontaktit, rekomandimet dhe hapat e ardhshëm.',
    'fcc.page.howto.nfc_card_offline.step_4' => 'Partneri vazhdon rrugëtimin përmes kontaktit, udhëzimeve për referimin ose ndjekjes së mëtejshme.',
    'fcc.page.howto.ai_product_assistants.name' => 'Si i udhëzojnë asistentët e IA-së vizitorët drejt produkteve dhe hapit të radhës',
    'fcc.page.howto.ai_product_assistants.description' => 'Hapa që shpjegojnë se si asistentët e AI brenda FCC i ndihmojnë vizitorët të eksplorojnë produktet dhe të kalojnë te hapi i duhur i radhës.',
    'fcc.page.howto.ai_product_assistants.step_1' => 'Vizitori bën një pyetje brenda aplikacionit FCC ose në bllokun AI.',
    'fcc.page.howto.ai_product_assistants.step_2' => 'Asistenti me AI sugjeron produkte të përshtatshme dhe udhëzime të dobishme.',
    'fcc.page.howto.ai_product_assistants.step_3' => 'Sistemi e orienton vizitorin drejt kontaktit, një shpjegimi më të hollësishëm ose rrugës së blerjes.',
    'fcc.page.howto.ai_product_assistants.step_4' => 'Partneri ka një rrugë më të qartë dhe më të thjeshtë nga interesi te rekomandimi ose biseda.',
    'fcc.core_gate.biolinks_disabled' => 'Përfundo edukimin e FCC për të aktivizuar FCC Apps.',
    'global.emails.billing_warning_first.subject' => 'Nuk mundëm të rinovonim planin tënd {{PLAN_NAME}}',
    'global.emails.billing_warning_first.body' => 'Përshëndetje {{NAME}},<br /><br />Nuk mundëm ta përpunonim rinovimin tënd të fundit për planin {{PLAN_NAME}}.<br /><br />Arsyeja: {{FAILURE_REASON}}<br />Përpjekja e radhës për pagesë: {{NEXT_PAYMENT_ATTEMPT}}<br />Qasja me periudhë tolerance deri më: {{GRACE_UNTIL}}<br /><br />Kontrollo mënyrën e pagesës këtu: <a href="{{USER_PLAN_LINK}}">{{USER_PLAN_LINK}}</a><br /><br />Mund t\'i kontrollosh faturat edhe këtu: <a href="{{USER_PAYMENTS_LINK}}">{{USER_PAYMENTS_LINK}}</a>',
    'global.emails.billing_warning_second.subject' => 'Urgjente: qasja jote me pagesë është pranë kalimit në një plan më të ulët',
    'global.emails.billing_warning_second.body' => 'Përshëndetje {{NAME}},<br /><br />Nuk arritëm ende të rinovojmë planin tënd {{PLAN_NAME}}.<br /><br />Arsyeja: {{FAILURE_REASON}}<br />Përpjekja e radhës për pagesë: {{NEXT_PAYMENT_ATTEMPT}}<br />Qasja me afat shtesë deri më: {{GRACE_UNTIL}}<br /><br />Nëse pagesa nuk kryhet deri në atë moment, qasja jote do të kalojë te {{FALLBACK_PLAN_NAME}}.<br /><br />Përditëso të dhënat e faturimit këtu: <a href="{{USER_PLAN_LINK}}">{{USER_PLAN_LINK}}</a>',
    'global.emails.billing_paused.subject' => 'Qasja jote me pagesë është pezulluar derisa pagesa të kryhet me sukses',
    'global.emails.billing_paused.body' => 'Përshëndetje {{NAME}},<br /><br />Nuk mundëm të përpunonim rinovimin e fundit për planin tënd {{PLAN_NAME}}, ndaj qasja jote me pagesë është ulur përkohësisht.<br /><br />Arsyeja: {{FAILURE_REASON}}<br />Përpjekja e radhës për pagesë: {{NEXT_PAYMENT_ATTEMPT}}<br />Periudha e riprovimit përfundon: {{GRACE_UNTIL}}<br /><br />Përditëso mënyrën e pagesës këtu: <a href="{{USER_PLAN_LINK}}">{{USER_PLAN_LINK}}</a><br /><br />Kur pagesa të kryhet me sukses, plani yt {{PLAN_NAME}} do të riaktivizohet automatikisht për periudhën e re të faturimit.',
    'global.emails.billing_recovered.subject' => 'Qasja jote me pagesë është rivendosur',
    'global.emails.billing_recovered.body' => 'Përshëndetje {{NAME}},<br /><br />Pagesa jote u rikuperua me sukses dhe plani yt {{PLAN_NAME}} është sërish aktiv.<br /><br />U rikuperua më: {{RECOVERED_AT}}<br />Abonimi: {{STRIPE_SUBSCRIPTION_ID}}<br />Fatura: {{STRIPE_INVOICE_ID}}',
    'global.emails.billing_revoked.subject' => 'Rinovimi automatik i planit tënd tani është çaktivizuar',
    'global.emails.billing_revoked.body' => 'Përshëndetje {{NAME}},<br /><br />Nuk arritëm të arkëtonim pagesën për planin tënd {{PLAN_NAME}} gjatë periudhës së riprovimit, ndaj rinovimet automatike të ardhshme tani janë çaktivizuar.<br /><br />Kalimi në plan më të ulët u bë më: {{REVOKED_AT}}<br />Arsyeja: {{FAILURE_REASON}}<br />Plani aktual rezervë: {{FALLBACK_PLAN_NAME}}<br /><br />Për të aktivizuar sërish PRO, nis një abonim të ri këtu: <a href="{{USER_PLAN_LINK}}">{{USER_PLAN_LINK}}</a>',
    'global.notifications.billing_warning_first.title' => 'U zbulua një problem me pagesën për {{PLAN_NAME}}',
