    'fcc_ai.platform.note_admin' => 'Detajet teknike mbeten të disponueshme më poshtë në seksione që mund të hapen, ndërsa ekrani kryesor mbetet i pastër.',
    'fcc_ai.platform.note_user' => 'Shih në një vend të vetëm si aktivizohet AI në aplikacion, si funksionon Coach dhe ku regjistrohen bisedat dhe klientët potencialë.',
    'fcc_ai.platform.list.app_blocks_title' => 'Blloqe AI në aplikacion',
    'fcc_ai.platform.list.app_blocks_text' => 'AI publike aktivizohet duke shtuar një bllok AI te cilësimet e FCC App. Pasi të shtohet, AI shfaqet në atë aplikacion.',
    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'Coach është gjithmonë i disponueshëm brenda FCC, i lidhur me planin e rritjes dhe i krijuar për të mbështetur platformën, rrjetet sociale, komunikimin dhe zhvillimin e biznesit.',
    'fcc_ai.platform.list.single_ai_title' => 'Një AI për aplikacion',
    'fcc_ai.platform.list.single_ai_text' => 'Vetëm një këshilltar AI mund të jetë aktiv në një FCC App të vetme. Nëse është shtuar tashmë një bllok AI, shtimi i një tjetri do të shfaqë një paralajmërim.',
    'fcc_ai.platform.list.leads_title' => 'Kontakte të mundshme nga AI',
    'fcc_ai.platform.list.leads_text' => 'Kontaktet e mundshme të krijuara nga AI ruhen në kutinë hyrëse ekzistuese /data dhe lidhen me bisedën përkatëse.',
    'fcc_ai.guide.title' => 'Si të përdorësh FCC AI',
    'fcc_ai.guide.subtitle' => 'Këta udhëzues të shkurtër shpjegojnë çfarë mund të bëjë secila AI dhe si të përfitosh sa më shumë prej saj në punën e përditshme.',
    'fcc_ai.guide.coach.title' => 'AI Coach',
    'fcc_ai.guide.coach.summary' => 'Mbështetje për punën në FCC, planin tënd të rritjes dhe hapat e ardhshëm praktikë.',
    'fcc_ai.guide.coach.intro' => 'FCC Coach është asistenti yt personal brenda platformës. Ai lidhet me planin tënd të rritjes dhe të ndihmon të jesh i qartë për hapin më të dobishëm që mund të ndërmarrësh.',
    'fcc_ai.guide.coach.point_1' => 'Mund të ndihmojë me planifikimin, përparësitë, përqendrimin dhe hapin e radhës kur ndihesh i/e bllokuar ose nuk je i/e sigurt çfarë të bësh më pas.',
    'fcc_ai.guide.coach.point_2' => 'Jep ide për përmbajtjen, komunikimin, rrjetet sociale dhe veprimet e përditshme që mbështesin rritjen e biznesit.',
    'fcc_ai.guide.coach.point_3' => 'Të udhëzon në Your Growth Plan dhe të jep këshilla të lidhura me atë që të nevojitet tani.',
    'fcc_ai.guide.coach.tip' => 'Përfiton më shumë kur shkruan qartë ku ndodhesh, çfarë dëshiron të arrish dhe çfarë lloj ndihme të duhet tani.',
    'fcc_ai.guide.sales.title' => 'AI për shitje, rekomandime dhe bashkëpunim në biznes',
    'fcc_ai.guide.sales.summary' => 'AI publik që rekomandon produkte, përdor blogun dhe dallon interesin për bashkëpunim.',
    'fcc_ai.guide.sales.intro' => 'Kjo AI bisedon me vizitorët në aplikacionin tënd FCC, i ndihmon me produkte për njerëz ose kafshë shtëpiake dhe i orienton drejt hapit të radhës, blerjes ose bashkëpunimit në biznes.',
    'fcc_ai.guide.sales.point_1' => 'U përgjigjet pyetjeve, rekomandon produkte dhe mund ta drejtojë vizitorin te artikulli përkatës i blogut FCC për një shpjegim më të hollësishëm.',
    'fcc_ai.guide.sales.point_2' => 'Ai e shoqëron vizitorin gjatë gjithë rrjedhës, nga pyetja e parë deri te biseda e vazhdueshme në blog ose te kontakti.',
    'fcc_ai.guide.sales.point_3' => 'Mund të mbledhë të dhëna nga vizitorët e interesuar dhe të ruajë një kontakt potencial, në mënyrë që partneri të mund ta kontaktojë më pas.',
    'fcc_ai.guide.sales.point_4' => 'Mund të dallojë interesin për biznesin dhe të mbështesë sponsorizimin duke e orientuar vizitorin drejt hapit tjetër me vlerë.',
    'fcc_ai.guide.sales.tip' => 'Funksionon më mirë kur toni është i qartë, rregullat të forta dhe logjika e rekomandimeve shpjegohet mirë.',
    'fcc_ai.guide.settings.title' => 'Cilësimet e këshilluesit',
    'fcc_ai.guide.settings.summary' => 'Ku përcakton si tingëllon, si përgjigjet dhe çfarë thekson AI-ja publike.',
    'fcc_ai.guide.settings.intro' => 'Te cilësimet publike të këshilltarit të AI-së mund ta përshtatësh komunikimin që të përputhet me stilin tënd, audiencën dhe qëllimin e aplikacionit.',
    'fcc_ai.guide.settings.point_1' => 'Emri dhe gjuha e asistentit përcaktojnë mënyrën si prezantohet AI-ja dhe gjuhën që përdor natyrshëm.',
    'fcc_ai.guide.settings.point_2' => 'Toni e ndihmon AI-n të tingëllojë këshillues, mbështetës, miqësor ose më i drejtpërdrejtë, në varësi të asaj që dëshiron.',
    'fcc_ai.guide.settings.point_3' => 'Te udhëzimet për personazhin, përshkruaj stilin që dëshiron: qasje më të ngrohtë, përgjigje më të shkurtra, më shumë pyetje, më shumë fokus te produktet ose më shumë fokus te biznesi.',
    'fcc_ai.guide.settings.point_4' => 'Te rregullat dhe kufizimet, përcakto çfarë duhet të përmendë gjithmonë AI, çfarë duhet të shmangë dhe si duhen formuluar rekomandimet.',
    'fcc_ai.guide.settings.tip' => 'Udhëzimet e shkurtra dhe konkrete zakonisht funksionojnë më mirë. Shkruaji sikur po shpjegon se si duhet t’i flasë një këshilltar i mirë një vizitori.',
    'fcc_ai.guide.inbox.title' => 'Kutia hyrëse e IA-së për 30 ditët e fundit',
    'fcc_ai.guide.inbox.summary' => 'Vendi ku mund të ndjekësh bisedat dhe klientët potencialë, si dhe të përmirësosh komunikimin në bisedat me AI.',
    'fcc_ai.guide.inbox.intro' => 'Kutia hyrëse e AI-së tregon se si asistenti ka komunikuar realisht me përdoruesit. Është vendi më i mirë për të monitoruar cilësinë dhe për të vazhduar përmirësimin e asistentit.',
    'fcc_ai.guide.inbox.point_1' => 'Hap bisedat dhe shqyrto ku AI u përgjigj mirë dhe ku përgjigjja mund të ishte më e qartë ose më e dobishme.',
    'fcc_ai.guide.inbox.point_2' => 'Vëre se cilat pyetje përsëriten shpesh, që të mund të përmirësosh tonin, udhëzimet për personazhin dhe rregullat.',
    'fcc_ai.guide.inbox.point_3' => 'Nëse përdoruesit vazhdojnë të kërkojnë më shumë shpjegime, shkurtoji përgjigjet, shto hapa më të qartë ose drejtoji më mirë te blogu ose te kontaktet.',
    'fcc_ai.guide.inbox.point_4' => 'Gjurmo kontaktet e mundshme që sjell AI dhe përdori këto të dhëna për të kuptuar se ku biseda ndihmon më shumë në shitje dhe sponsorizim.',
    'fcc_ai.guide.inbox.tip' => 'Nëse vëren të njëjtin problem më shumë se një herë, rregullo menjëherë cilësimet e këshilluesit. Ndryshime të vogla në ton dhe rregulla shpesh sjellin përmirësim të madh.',
